import React, { useState, useEffect } from "react";
import "./Seo_shortform.css";
import { useLocation } from "react-router-dom";

function Seo_shortform({ videoThumbnail }) {
  const location = useLocation();
  const { message, results } = location.state || {};
  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");

  const getVideoUrl = (clipData, fileName) => {
    const baseUrl = "http://127.0.0.1:8000/media/";

    // Check for enhanced audio version first
    if (clipData?.audio_processing?.enhanced_video_path) {
      const enhancedAudioFileName = clipData.audio_processing.enhanced_video_path.split('\\').pop();
      return `${baseUrl}${enhancedAudioFileName}`;
    }

    // Check for enhanced video version second
    if (clipData?.video_processing?.enhanced_video_path) {
      const enhancedVideoFileName = clipData.video_processing.enhanced_video_path.split('\\').pop();
      return `${baseUrl}${enhancedVideoFileName}`;
    }

    // Fall back to original file
    return `${baseUrl}${fileName}`;
  };

  useEffect(() => {
    console.log("Received results:", results);
  }, [results]);

  return (
    <div className="seo-app">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      <main className="main-content">
        <button className="clipper-btn">Go to Clipper</button>
        <h3 className="seo-label">SEO Data for Clips</h3>

        <div className="clip-section">
          {Object.entries(results || {}).map(([fileName, clipData], index) => {
            const videoUrl = getVideoUrl(clipData, fileName);
            const seoData = clipData?.seo || {};
            const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
            const description = seoData.description || "No description available.";
            const title = seoData.title || "No title available.";
            const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

            return (
              <div key={index} className="clip-container">
                <div className="video-container">
                  <video className="video-player" controls width="100%" height="auto">
                    <source src={videoUrl} type="video/mp4" />
                    Your browser does not support the video tag.
                  </video>
                </div>

                <div className="customize-clip">
                  <h3 className="clip-label">SEO for Clip {index + 1}</h3>
                  <div className="seo-box">
                    <h2>Title</h2>
                    <p>{title}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Description</h2>
                    <p>{description}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Keywords</h2>
                    <p>{keywords}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Tags</h2>
                    <p>{tags}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
}

export default Seo_shortform;
